/**
 * A fixed-capacity least-recently-used cache.
 *
 * Entries live in slot arrays threaded by an intrusive doubly-linked list
 * (head = least recently used, tail = most recently used), with a Map from
 * key to slot index. Every operation is O(1) expected time.
 */
const NIL = -1;

export class LruCache {
  readonly #capacity: number;
  readonly #index = new Map<string, number>();
  #keys: string[] = [];
  #values: string[] = [];
  #prev: Int32Array;
  #next: Int32Array;
  #head = NIL;
  #tail = NIL;
  #freeSlots: number[] = [];

  constructor(capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError(`capacity must be a positive integer, got ${capacity}`);
    }
    this.#capacity = capacity;
    const initial = Math.min(capacity + 1, 1024);
    this.#prev = new Int32Array(initial);
    this.#next = new Int32Array(initial);
  }

  get size(): number {
    return this.#index.size;
  }

  /** Returns the value for `key` and marks it most recently used, or `undefined` on a miss. */
  get(key: string): string | undefined {
    const slot = this.#index.get(key);
    if (slot === undefined) return undefined;
    this.#moveToTail(slot);
    return this.#values[slot];
  }

  /** Inserts or overwrites `key`, marks it most recently used, and evicts if over capacity. */
  set(key: string, value: string): void {
    const existing = this.#index.get(key);
    if (existing !== undefined) {
      this.#values[existing] = value;
      this.#moveToTail(existing);
      return;
    }
    const slot = this.#allocateSlot();
    this.#keys[slot] = key;
    this.#values[slot] = value;
    this.#index.set(key, slot);
    this.#linkAtTail(slot);
    if (this.#index.size > this.#capacity) this.#removeSlot(this.#head);
  }

  /** Removes `key`; returns whether it was present. */
  delete(key: string): boolean {
    const slot = this.#index.get(key);
    if (slot === undefined) return false;
    this.#removeSlot(slot);
    return true;
  }

  #allocateSlot(): number {
    const reused = this.#freeSlots.pop();
    if (reused !== undefined) return reused;
    const slot = this.#keys.length;
    if (slot >= this.#prev.length) this.#grow();
    this.#keys.push('');
    this.#values.push('');
    return slot;
  }

  #grow(): void {
    const length = Math.min(this.#prev.length * 2, this.#capacity + 1);
    const prev = new Int32Array(length);
    const next = new Int32Array(length);
    prev.set(this.#prev);
    next.set(this.#next);
    this.#prev = prev;
    this.#next = next;
  }

  #removeSlot(slot: number): void {
    this.#unlink(slot);
    this.#index.delete(this.#keys[slot]);
    this.#keys[slot] = '';
    this.#values[slot] = '';
    this.#freeSlots.push(slot);
  }

  #moveToTail(slot: number): void {
    if (slot === this.#tail) return;
    this.#unlink(slot);
    this.#linkAtTail(slot);
  }

  #linkAtTail(slot: number): void {
    this.#prev[slot] = this.#tail;
    this.#next[slot] = NIL;
    if (this.#tail === NIL) this.#head = slot;
    else this.#next[this.#tail] = slot;
    this.#tail = slot;
  }

  #unlink(slot: number): void {
    const prev = this.#prev[slot];
    const next = this.#next[slot];
    if (prev === NIL) this.#head = next;
    else this.#next[prev] = next;
    if (next === NIL) this.#tail = prev;
    else this.#prev[next] = prev;
  }
}

/**
 * LRU cache simulator: reads a capacity and a stream of commands from stdin
 * and writes one line of output per GET, DEL and SIZE command.
 */
import { readFileSync, writeSync } from 'node:fs';
import { LruCache } from './lru-cache.ts';

const LINE_BREAK = /\r\n|\r|\n/;

/** Runs one command line against the cache, appending any output to `out`. */
function execute(cache: LruCache, line: string, out: string[]): void {
  const sp1 = line.indexOf(' ');
  const command = sp1 < 0 ? line : line.slice(0, sp1);
  const rest = line.slice(sp1 + 1);
  switch (command) {
    case 'SET': {
      const sp2 = rest.indexOf(' ');
      if (sp2 < 0) throw new Error(`malformed SET command: ${line}`);
      cache.set(rest.slice(0, sp2), rest.slice(sp2 + 1));
      break;
    }
    case 'GET':
      out.push(cache.get(rest) ?? 'NULL');
      break;
    case 'DEL':
      out.push(cache.delete(rest) ? '1' : '0');
      break;
    case 'SIZE':
      out.push(String(cache.size));
      break;
    default:
      // Unknown commands are ignored.
      break;
  }
}

/** Processes the whole input, returning the program's output. */
export function run(input: string): string {
  const lines = input.split(LINE_BREAK);
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();
  if (lines.length === 0) return '';

  const capacity = Number.parseInt(lines[0].trim(), 10);
  if (!Number.isSafeInteger(capacity)) throw new Error(`invalid capacity: ${lines[0]}`);
  const cache = new LruCache(capacity);
  const out: string[] = [];
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (line !== '') execute(cache, line, out);
  }
  return out.length === 0 ? '' : out.join('\n') + '\n';
}

function writeAll(fd: number, data: Buffer): void {
  let offset = 0;
  while (offset < data.length) {
    try {
      offset += writeSync(fd, data, offset);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== 'EAGAIN') throw err;
    }
  }
}

function main(): void {
  const input = readFileSync(0, 'latin1');
  writeAll(1, Buffer.from(run(input), 'latin1'));
}

main();
